steps.body:
A **stack** is last in, first out, like a pile of plates. An array is a fast stack at its end: `push` adds an item on top, `pop` removes the top item and returns it, and `stack[stack.length - 1]`, or the shorter `stack.at(-1)`, peeks at it without removing it. All three are O(1), because no other item moves.

```javascript
const stack = [];
stack.push("a");
stack.push("b");
console.log(stack.at(-1)); // b
console.log(stack.pop()); // b
console.log(stack.length); // 1
```

On an empty array, `pop()` and `at(-1)` return `undefined` instead of throwing, so a mistake fails quietly. Check `stack.length > 0` whenever the stack might be empty.

A stack matches things that nest, like brackets. Push every opening bracket. A closing bracket must match the newest bracket still open, which is the top of the stack, so pop it and compare. At the end the stack must be empty, or some bracket was never closed:

```javascript
const openerFor = new Map([[")", "("], ["]", "["], ["}", "{"]]);
const stack = [];
let ok = true;
for (const ch of "{[()]}(") {
  if (!openerFor.has(ch)) {
    stack.push(ch);
  } else if (stack.pop() !== openerFor.get(ch)) {
    ok = false;
    break;
  }
}
console.log(ok && stack.length === 0); // false, the last ( is never closed
```

Popping an empty stack gives `undefined`, which never equals an opener, so a closer with nothing open fails the check too.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");
const n = Number(lines[0]);
const openerFor = new Map([[")", "("], ["]", "["], ["}", "{"]]);

function firstProblem(code) {
  const open = []; // positions of the brackets still open
  for (let i = 0; i < code.length; i++) {
    const ch = code[i];
    if ("([{".includes(ch)) {
      open.push(i);
    } else if (openerFor.has(ch)) {
      if (open.length === 0) {
        return `${ch} at ${i + 1} closes nothing`;
      }
      const top = open.pop();
      if (code[top] !== openerFor.get(ch)) {
        return `${ch} at ${i + 1} does not match ${code[top]} at ${top + 1}`;
      }
    }
  }
  if (open.length > 0) {
    return `${code[open[0]]} at ${open[0] + 1} is never closed`;
  }
  return "ok";
}

for (const line of lines.slice(1, n + 1)) {
  console.log(`${line} -> ${firstProblem(line)}`);
}

