const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");
const n = Number(lines[0]);

function firstProblem(tags) {
  const open = []; // the opening tags still open
  for (const tag of tags) {
    if (!tag.startsWith("</")) {
      open.push(tag);
    } else if (open.length === 0) {
      return `${tag} closes nothing`;
    } else if (open.at(-1) !== "<" + tag.slice(2)) {
      return `${tag} does not match ${open.at(-1)}`;
    } else {
      open.pop();
    }
  }
  if (open.length > 0) {
    return `${open[0]} is never closed`;
  }
  return "ok";
}

for (const line of lines.slice(1, n + 1)) {
  const tags = line.trim().split(/\s+/);
  console.log(`${line} -> ${firstProblem(tags)}`);
}

steps.body:
A **queue** is first in, first out, like a line at a counter. `push` joins the back and `shift()` leaves from the front, but `shift()` moves every remaining item down one slot. Each call is O(n), so working through a queue of n items costs O(n^2). Node hides this on small arrays, but a queue of 100,000 jobs gets slow.

The fast version never removes from the front. A `head` index points at the next item to serve:

```javascript
const queue = ["ann", "bo"];
let head = 0;
queue.push("cy"); // joins the back
console.log(queue[head++]); // ann
console.log(queue.length - head); // 2, still waiting
```

`queue[head++]` reads the front item, then moves `head` on. The queue is empty when `head === queue.length`, and every step is O(1).

Served items stay in the array behind `head`. In a queue that runs for a long time they waste memory, so compact it once they make up more than half the array:

```javascript harness
const queue = ["ann", "bo", "cy", "dee"];
let head = 3;
{{code}}
console.log(`${queue.join(" ")}, head ${head}`);
```

```javascript
if (head * 2 > queue.length) {
  queue.splice(0, head); // drop the served items
  head = 0;
}
```

Each compaction moves fewer items than were served since the last one, so on average every step stays O(1).

example.code:
const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");
const n = Number(lines[0]);
const perTurn = 2; // pages the printer prints per turn

const queue = lines.slice(1, n + 1).map((line) => {
  const [name, pages] = line.trim().split(/\s+/);
  return { name, left: Number(pages) };
});
let head = 0; // the next job to serve
let turn = 0;

while (head < queue.length) {
  const job = queue[head++];
  turn++;
  job.left -= perTurn;
  if (job.left > 0) {
    queue.push(job); // not done: back of the line
  } else {
    console.log(`${job.name} done on turn ${turn}`);
  }
  if (head * 2 > queue.length) {
    queue.splice(0, head); // drop the served part
    head = 0;
  }
}

