const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");
const [n, q] = lines[0].trim().split(/\s+/).map(Number);

const queue = lines.slice(1, n + 1).map((line) => {
  const [name, ms] = line.trim().split(/\s+/);
  return { name, left: Number(ms) };
});
let head = 0; // the next task to run
let clock = 0;

while (head < queue.length) {
  const task = queue[head++];
  const ran = Math.min(q, task.left);
  clock += ran;
  task.left -= ran;
  if (task.left > 0) {
    queue.push(task);
  } else {
    console.log(`${task.name} finished at ${clock}`);
  }
  if (head * 2 > queue.length) {
    queue.splice(0, head);
    head = 0;
  }
}

steps.body:
Some questions ask, for every item, about the next item that's bigger: the next warmer day, the next higher price. Checking every later item is O(n^2). A **monotonic stack** answers them all in one pass.

The stack holds the indexes still waiting for an answer, and their values only go down from bottom to top. When a new value arrives, it's the answer for every waiting index with a smaller value, so pop those and answer them. Then push the new index:

```javascript
const nums = [2, 7, 3, 5, 4, 6, 8];
const next = new Array(nums.length).fill(-1);
const stack = []; // indexes still waiting for a bigger value
for (let i = 0; i < nums.length; i++) {
  while (stack.length > 0 && nums[stack.at(-1)] < nums[i]) {
    next[stack.pop()] = nums[i];
  }
  stack.push(i);
}
console.log(next.join(" ")); // 7 8 5 6 6 8 -1
```

Keep **indexes**, not values. An index says where the answer goes, and it gives both the value `nums[j]` and the distance `i - j`. Indexes still on the stack at the end never met a bigger value, so they keep their -1. The strict `<` leaves an equal value waiting, since it isn't bigger.

It's O(n) even with a `while` inside the `for`. Each index is pushed once and popped at most once, so the `while` runs at most n times over the whole scan. The stack needs O(n) memory when the values only go down.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const heights = input.trim().split(/\s+/).map(Number);
const nextTaller = new Array(heights.length).fill(-1); // an index, or -1 for none
const stack = []; // indexes still waiting, heights falling from bottom to top

for (let i = 0; i < heights.length; i++) {
  while (stack.length > 0 && heights[stack.at(-1)] < heights[i]) {
    nextTaller[stack.pop()] = i;
  }
  stack.push(i);
}

for (let i = 0; i < heights.length; i++) {
  const j = nextTaller[i];
  if (j === -1) {
    console.log(`Building ${i + 1} (${heights[i]} m): none taller to the east`);
  } else {
    console.log(`Building ${i + 1} (${heights[i]} m): next taller is building ${j + 1} (${heights[j]} m)`);
  }
}

